{
  "hypotheses": [
    {
      "claim": "pMap does not properly handle the case where a mapper returns pMapSkip for an item that is processed after the iterable has been marked as done, leading to incorrect result ordering.",
      "path": "index.js",
      "start_line": 110,
      "end_line": 132,
      "evidence": "resolvingCount++;

			// Intentionally detached
			(async () => {
				try {
					const element = await nextItem.value;

					if (isResolved) {
						return;
					}

					const value = await mapper(element, index);

					// Use Map to stage the index of the element.
					if (value === pMapSkip) {
						skippedIndexesMap.set(index, value);
					}

					result[index] = value;

					resolvingCount--;
					await next();
				} catch (error) {
					if (stopOnError) {
						reject(error);
					} else {
						errors.push(error);
						resolvingCount--;

						// In that case we can't really continue regardless of `stopOnError` state
						// since an iterable is likely to continue throwing after it throws once.
						// If we continue calling `next()` indefinitely we will likely end up
						// in an infinite loop of failed iteration.
						try {
							await next();
						} catch (error) {
							reject(error);
						}
					}
				}
			})();",
      "reproduction": {
        "code": "const {default: pMap, pMapSkip} = await load('./index.js');

async function* asyncIterable() {
  yield Promise.resolve(1);
  yield Promise.resolve(2);
  // Simulate a slow iterable that finishes after some items are processed
  await new Promise(resolve => setTimeout(resolve, 10));
  yield Promise.resolve(3);
}

const result = await pMap(asyncIterable(), async (value, index) => {
  if (index === 1) {
    // Return pMapSkip for the second item
    return pMapSkip;
  }
  return value * 2;
}, {concurrency: 2});

assert.deepEqual(result, [2, 6]);"
      }
    }
  ]
}
